#include "Driver_UARTP.h"

/**
 * @brief  Using UART to output char.
 *
 * @param[in]  ch   Char to output.
 */
void wm_putchar(char ch)
{
#ifdef __UART_PRINT
    UART_16550->DLL_THR_RBR = ch;
    WM_WAIT_FOREVER(UART_16550->LSR & 0x20);
#else
    volatile char* out;
    out  = (volatile char*)&(UART_16550->DLL_THR_RBR);
    *out = ch;
#endif
}

#ifdef __UART_PRINT
/**
 * @brief  Setting UART for log input/output.
 *
 * @param[in]  baund_rate   Baund rate to set.
 */
static void WM_UARTP_Init(uint32_t baund_rate)
{
    uint32_t div;
    div = ((__UART_REF_CLK + baund_rate / 2) / baund_rate) - 1;

    UART_16550->LCR         = 0x88; // 0x80;
    UART_16550->DLM_IER     = (div & 0xff00) >> 8;
    UART_16550->DLL_THR_RBR = (div & 0x00ff);
    UART_16550->LCR         = 0x03;
}

/**
 * @brief  Uart initialization api.
 */
void WM_UARTP_Initialize(void)
{
    WM_UARTP_Init(115200);
}

/**
 * @brief  Bottom api for UART log output.
 */
ssize_t _write(int fd, const void* ptr, size_t len)
{
    size_t i;

    if (!isatty(fd))
    {
        return -1;
    }

    const uint8_t* writebuf = (const uint8_t*)ptr;

    for (i = 0; i < len; i++)
    {
        wm_putchar(writebuf[i]);
    }

    return len;
}

#endif // __UART_PRINT

void printf_putch(int ch, void** data)
{
    wm_putchar(ch);
}

static long long getint(va_list* ap, int lflag)
{
    if (lflag >= 2)
        return va_arg(*ap, long long);
    else if (lflag)
        return va_arg(*ap, long);
    else
        return va_arg(*ap, int);
}

static unsigned long long getuint(va_list* ap, int lflag)
{
    if (lflag >= 2)
        return va_arg(*ap, unsigned long long);
    else if (lflag)
        return va_arg(*ap, unsigned long);
    else
        return va_arg(*ap, unsigned int);
}

static double getdouble(va_list* ap, int lflag)
{
    if (lflag >= 1)
    {
        return va_arg(*ap, double);
    }
    else
    {
        return (double)va_arg(*ap, double);
    }
}

NO_UNROLL static inline void printnum(void (*putch)(int, void**),
                                      void**             putdat,
                                      unsigned long long num,
                                      unsigned           base,
                                      int                width,
                                      int                padc,
                                      int                hex_A)
{
    unsigned digs[sizeof(num) * CHAR_BIT];
    int      pos = 0;

    for (;;)
    {
        digs[pos++] = num % base;
        if (num < base)
            break;
        num /= base;
    }

    while (width-- > pos)
        putch(padc, putdat);

    while (pos-- > 0)
        putch(digs[pos] + (digs[pos] >= 10 ? hex_A - 10 : '0'), putdat);
}

NO_UNROLL static void
printdoubleF(void (*putch)(int, void**), void** putdat, double num, int width, int precision, int padc)
{
    if (num < 0)
    {
        putch('-', putdat);
        num = -num;
    }

    // 处理整数部分
    unsigned long long integer_part = (unsigned long long)num;
    num -= integer_part;

    printnum(putch, putdat, integer_part, 10, width, padc, '0');

    // 处理小数部分
    if (precision > 0)
    {
        int i = 0;
        putch('.', putdat);
        for (i = 0; i < precision; i++)
        {
            num *= 10;
            int digit = (int)num;
            putch(digit + '0', putdat);
            num -= digit;
        }
    }
}

NO_UNROLL void vprintfmt(void (*putch)(int, void**), void** putdat, const char* fmt, va_list ap)
{
    register const char* p;
    const char*          last_fmt;
    register int         ch;
    int                  err;
    unsigned long long   num;
    int                  base;
    int                  lflag;
    int                  width;
    int                  precision;
    int                  altflag;
    char                 padc;
    int                  hex_A = 'a';
    double               num_double;
    for (;;)
    {
        while ((ch = *(unsigned char*)fmt) != '%')
        {
            if (ch == '\0')
                return;
            ++fmt;
            putch(ch, putdat);
        }
        ++fmt;

        // Process a %-escape sequence
        last_fmt  = fmt;
        padc      = ' ';
        width     = -1;
        precision = -1;
        lflag     = 0;
        altflag   = 0;

    reswitch:
        switch (ch = *(unsigned char*)fmt++)
        {
            // flag to pad on the right
            case '-':
                padc = '-';
                goto reswitch;

                // flag to pad with 0's instead of spaces
            case '0':
                padc = '0';
                goto reswitch;

                // width field
            case '1':
            case '2':
            case '3':
            case '4':
            case '5':
            case '6':
            case '7':
            case '8':
            case '9':
                for (precision = 0;; ++fmt)
                {
                    precision = precision * 10 + ch - '0';
                    ch        = *fmt;
                    if (ch < '0' || ch > '9')
                        break;
                }
                goto process_precision;

            case '*':
                precision = va_arg(ap, int);
                goto process_precision;

            case '.':
                if (width < 0)
                    width = 0;
                goto reswitch;

            case '#':
                altflag = 1;
                goto reswitch;

            process_precision:
                if (width < 0)
                {
                    width     = precision;
                    precision = -1;
                }
                goto reswitch;

                // long flag (doubled for long long)
            case 'l':
                lflag++;
                goto reswitch;

                // character
            case 'c':
                putch(va_arg(ap, int), putdat);
                break;

                // string
            case 's':
                if ((p = va_arg(ap, char*)) == NULL)
                    p = "(null)";
                if (width > 0 && padc != '-')
                    for (width -= strnlen(p, precision); width > 0; width--)
                        putch(padc, putdat);
                for (; (ch = *p) != '\0' && (precision < 0 || --precision >= 0); width--)
                {
                    putch(ch, putdat);
                    p++;
                }
                for (; width > 0; width--)
                    putch(' ', putdat);
                break;

                // (signed) decimal
            case 'd':
                num = getint(&ap, lflag);
                if ((long long)num < 0)
                {
                    putch('-', putdat);
                    num = -(long long)num;
                }
                base = 10;
                goto signed_number;

            case 'f':
                // #ifndef nopfloat
                num_double = getdouble(&ap, lflag);

                if (precision < 0)
                {
                    precision = 6; // 默认精度为 6
                }
                printdoubleF(putch, putdat, num_double, width, precision, padc);
                // #endif
                break;

                // unsigned decimal
            case 'u':
                base = 10;
                goto unsigned_number;

                // (unsigned) octal
            case 'o':
                // should do something with padding so it's always 3 octits
                base = 8;
                goto unsigned_number;

                // pointer
            case 'p':
                // static_assert(sizeof(long) == sizeof(void*));
                lflag = 1;
                putch('0', putdat);
                putch('x', putdat);
                /* fall through to 'x' */

                // (unsigned) hexadecimal
            case 'x':
                hex_A = 'a';
                base  = 16;
                goto unsigned_number;

            case 'X':
                hex_A = 'A';
                base  = 16;
            unsigned_number:
                num = getuint(&ap, lflag);
            signed_number:
                printnum(putch, putdat, num, base, width, padc, hex_A);
                break;

                // escaped '%' character
            case '%':
                putch(ch, putdat);
                break;

                // unrecognized escape sequence - just print it literally
            default:
                putch('%', putdat);
                fmt = last_fmt;
                break;
        }
    }
}

__attribute__((weak)) int wm_printf(const char* fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);

    vprintfmt(printf_putch, NULL, fmt, ap);

    va_end(ap);

    return 0;
}

