#ifndef __CORE_CACHE_H__
#define __CORE_CACHE_H__

#if defined(__ICACHE_PRESENT) && (__ICACHE_PRESENT == 1)
#if defined(M05X_SERIES) || defined(M13X_SERIES)
/**
 * @defgroup WMSIS_MSS_Registers.Register Define and Type Definitions Of MSS.
 * @ingroup WMSIS_MSS_Registers.
 * @brief Memory Subsystem Memory-Mapped register definition.
 *
 * @{
 */
/**
 * @brief  Memory Subsystem Memory-Mapped register definition. 
 */
 typedef struct
{
    __IOM uint32_t ICC_EN;                              /*!< Instruction cache enable register. */
    __IOM uint32_t ICC_INV;                             /*!< Instruction cache invalidate register. */
    __IOM uint32_t ICC_INV_ADDR;                        /*!< Instruction cache invalidate address register. */
} MSS_MMR;

#define WING_CACHE ((MSS_MMR *)__MSS_REG_BASEADDR)      /*!< Pointer to Cache configuration register. */
/** @}  End of Group WMSIS_MSS_Registers */

/**
 * @defgroup WMSIS_CACHE_Funtions  Cache Configure Functions
 * @ingroup WMSIS_CACHE_Funtions
 * @brief   Functions to configure the Cache.
 * @{
 */
/**
 * @brief  Instruction cache enable.
 * 
 */
__STATIC_FORCEINLINE void __icache_Enable(void)
{
    WING_CACHE->ICC_EN = 1;
}

/**
 * @brief  Instruction cache disable.
 * 
 */
__STATIC_FORCEINLINE void __icache_Disable(void)
{
    WING_CACHE->ICC_EN = 0;
}

/**
 * @brief  Invalidate all instruction cache.
 * 
 */
__STATIC_FORCEINLINE void __icache_InvalidateAll(void)
{
    WING_CACHE->ICC_INV = 1;
}

/**
 * @brief  Invalidate a instruction cache line by address.
 * 
 * @param[in]  addr   Address of the instruction cache line to invalidate.
 * 
 */
__STATIC_FORCEINLINE void __icache_InvalidateLine(wm_base_t addr)
{
    WM_ASSERT(addr < (__ICACHE_SIZE / __ICACHE_WAY_NUM / __ICACHE_LINE_SIZE));

    WING_CACHE->ICC_INV_ADDR = addr;
    WING_CACHE->ICC_INV      = 2;
}
#elif defined(M51X_SERIES)
/**
 * @brief  Instruction cache enable.
 * 
 */
__STATIC_FORCEINLINE void __icache_Enable(void)
{
    __CSR_SET(CSR_MSYSCFG, 1 << 0);
}

/**
 * @brief  Instruction cache disable.
 * 
 */
__STATIC_FORCEINLINE void __icache_Disable(void)
{
    __CSR_CLEAR(CSR_MSYSCFG, 1 << 0);
}
/** @}  End of Group WMSIS_CACHE_Funtions */
#endif
#endif // defined(__ICACHE_PRESENT) && (__ICACHE_PRESENT == 1)

#if defined(__DCACHE_PRESENT) && (__DCACHE_PRESENT == 1) && defined(M51X_SERIES)
/**
 * @brief  Data cache enable.
 * 
 */
__STATIC_FORCEINLINE void __dcache_Enable(void)
{
    __CSR_SET(CSR_MSYSCFG, 1 << 1);
}

/**
 * @brief  Data cache disable.
 * 
 */
__STATIC_FORCEINLINE void __dcache_Disable(void)
{
    __CSR_CLEAR(CSR_MSYSCFG, 1 << 1);
}
#endif // defined(__DCACHE_PRESENT) && (__DCACHE_PRESENT == 1) && defined(M51X_SERIES)

/**
 * @brief  Invalidate a cache address.
 * 
 * @param[in]  addr   Address of cache to invalidate.
 */
__STATIC_FORCEINLINE void __cbo_Invalidate(uint32_t* addr)
{
    __ASM_VOLATILE("cbo.inval (%0)" ::"r"(addr));
}

/**
 * @brief  Clean a cache address.
 * 
 * @param[in]  addr   Address of cache to Clean.
 */
__STATIC_FORCEINLINE void __cbo_Clean(uint32_t* addr)
{
    __ASM_VOLATILE("cbo.clean (%0)" ::"r"(addr));
}

/**
 * @brief  Flush a cache address.
 * 
 * @param[in]  addr   Address of cache to Flush.
 */
__STATIC_FORCEINLINE void __cbo_Flush(uint32_t* addr)
{
    __ASM_VOLATILE("cbo.flush (%0)" ::"r"(addr));
}

/**
 * @brief  Zero a cache address.
 * 
 * @param[in]  addr   Address of cache to Zero.
 */
__STATIC_FORCEINLINE void __cbo_Zero(uint32_t* addr)
{
    __ASM_VOLATILE("cbo.zero (%0)" ::"r"(addr));
}

/**
 * @brief  Prefetch cache address for later read.
 * 
 * @param[in]  addr   Address of cache to Prefetch.
 */
__STATIC_FORCEINLINE void __cbo_PrefetchRead(uint32_t* addr)
{
    __ASM_VOLATILE("prefetch.r 0(%0)" ::"r"(addr));
}

/**
 * @brief  Prefetch cache address for later write.
 * 
 * @param[in]  addr   Address of cache to Prefetch.
 */
__STATIC_FORCEINLINE void __cbo_PrefetchWrite(uint32_t* addr)
{
    __ASM_VOLATILE("prefetch.w 0(%0)" ::"r"(addr));
}

/**
 * @brief  Prefetch cache address for later instruction fetch.
 * 
 * @param[in]  addr   Address of cache to Prefetch.
 */
__STATIC_FORCEINLINE void __cbo_PrefetchInst(uint32_t* addr)
{
    __ASM_VOLATILE("prefetch.i 0(%0)" ::"r"(addr));
}

#endif /*__CORE_CACHE_H__*/

