#ifndef __CORE_CLIC_H__
#define __CORE_CLIC_H__

/**
 * @defgroup WMSIS_Core_CLIC_Registers.Register Define and Type Definitions Of CLIC.
 * @ingroup WMSIS_Core_CLIC_Registers.
 * @brief CLIC Register Type definitions and defines.
 *
 * @{
 */
/* MTVEC/MTVT alignment factor define. */
#define MTVEC_CLINT_ALIGN_FACTOR    (0x03)        /*!< MTVEC alignment factor define for CLINT mode. */
#define MTVEC_CLIC_ALIGN_FACTOR     (0x3f)        /*!< MTVEC alignment factor define for CLIC mode. */
#define MTVT_ALIGN_FACTOR           (0x3f)        /*!< MTVT alignment factor define */

#if defined(__CLIC_PRESENT) && (__CLIC_PRESENT == 1)
/**
 * @brief CLIC trigger type definition. 
 */
typedef enum
{
    TRIG_HIGH_LEVEL = 0,        /**< High-level trigger type. */
    TRIG_RISING_EDGE,           /**< Rising-edge trigger type. */
    TRIG_LOW_LEVEL,             /**< LOW-level trigger type. */
    TRIG_FALLING_EDGE,          /**< FALLING-edge trigger type. */
} TRIG_TYPE;

/**
 * @brief  CLIC vector trigger mode type definition
 * @details In non-vectored mode, it jumps to the common base address held at mtvec
 * when interrupt triggered,but it jumps to the trap-handler function pointer 
 * specified in mtvt if in vectored mode. 
 */
typedef enum
{
    NONE_VECTORED_MODE = 0,     /**< CLIC non-vectored trigger Mode. */
    VECTORED_MODE,              /**< CLIC vectored trigger mode. */
} SHV_TYPE;

/**
 * @brief CLIC Memory-Mapped register definition for given interrupt i.
 */
typedef struct
{
    __IOM uint8_t IP;       /**< CLIC interrupt pending register for given interrupt i. */
    __IOM uint8_t IE;       /**< CLIC interrupt enable register for given interrupt i. */
    __IOM uint8_t ATTR;     /**< CLIC interrupt attribute register for given interrupt i. */
    __IOM uint8_t CTL;      /**< CLIC interrupt input control register for given interrupt i. */
} CONF_REG;

/**
 * @brief  CLIC Memory-Mapped register definition. 
 * @details These registers must be made accessible to the M-mode software running
 * on the hart,otherwise access will be prevented by system's standard memory protection
 * mechanisms.
 */
typedef struct
{
    __IOM uint32_t CFG;                 /*!< Machine CLIC configuration register. */
    __IM uint32_t RESERVED[0x3FF];
    CONF_REG config[__MAX_INT_NUM];     /*!< CLIC configuration register group,including:IP,IE,ATTR,CTL. */
} CLIC_MMR;

#define WING_CLIC ((CLIC_MMR *)__CLIC_REG_BASEADDR)     /*!< Pointer to CLIC configuration register. */

/* Bits 3..0 : Indicate how many upper bits are assigned to encode the interrupt level */
#define CLIC_CFG_NLBIT_POS (0U)                             /*!< Position of Nlbits field. */
#define CLIC_CFG_NLBIT_MSK (0x0fUL << CLIC_CFG_NLBIT_POS)   /*!< Bit Mask of Nlbits field. */

/* Bits 0 : Interrupt enable */
#define CLIC_IE_POS (0U)                   /*!< Position of interrupt enable field. */
#define CLIC_IE_MSK (0x1UL << CLIC_IE_POS) /*!< Bit Mask of interrupt enable field. */

/* Bits 0 : Interrupt pending */
#define CLIC_IP_PENDING_POS (0U)                           /*!< Position of interrupt pending field. */
#define CLIC_IP_PENDING_MSK (0x1UL << CLIC_IP_PENDING_POS) /*!< Bit mask of interrupt pending field. */

/* Bits 0 : shv */
#define CLIC_ATTR_SHV_POS (0U)                         /*!< Position of shv field. */
#define CLIC_ATTR_SHV_MSK (0x1UL << CLIC_ATTR_SHV_POS) /*!< Bit mask of shv field. */

/* Bits 1 : Interrupt type:level/edge select */
#define CLIC_ATTR_TRIG_POS (1U)                          /*!< Position of interrupt type field,0:level 1:edge. */
#define CLIC_ATTR_TRIG_MSK (0x1UL << CLIC_ATTR_TRIG_POS) /*!< Bit mask of interrupt type field. */

/* Bits 2 : Interrupt type:invert level/edge select */
#define CLIC_ATTR_POLARITY_POS (2U)                              /*!< Position of interrupt type invert field. */
#define CLIC_ATTR_POLARITY_MSK (0x1UL << CLIC_ATTR_POLARITY_POS) /*!< Bit mask of interrupt type invert field,0:high level/rising edge 1:low leve/falling edge. */

/* Bits 7..0 : Specify interrupt level and priority */
#define CLIC_CTRL_ALL_POS (0U)                          /*!< Position of interrupt level and priority field. */
#define CLIC_CTRL_ALL_MSK (0xffUL << CLIC_CTRL_ALL_POS) /*!< Bit mask of interrupt level and priority field. */

#define FAST_INT_PRIORITY (0xFF)
/** @}  End of Group WMSIS_Core_CLIC_Registers */

/**
 * @defgroup WMSIS_CLIC_Funtions  CLIC Configure Functions
 * @ingroup WMSIS_CLIC_Funtions
 * @brief   Functions configure the CLIC.
 * @{
 */
#if defined(__SMCSRIND_PRESENT) && (__SMCSRIND_PRESENT == 1)
#define CLIC_CTRL_ATTR_BASE         (0x1000)
#define CLIC_IP_IE_BASE             (0x1400)
#define CLIC_CFG_BASE               (0x14A0)
/**
 * @brief  Enable CLIC interrupt.
 *
 * @details Set CLIC IE bit for interrupt enable.
 *
 * @param[in]  irq  Number of int to enable.
 */
__STATIC_FORCEINLINE void __clic_EnableInt(INT_TYPE irq)
{
    uint32_t ie_reg;

    __CSR_WRITE(CSR_MISELECT, CLIC_IP_IE_BASE + irq / 32);

    ie_reg = __CSR_READ(CSR_MIREG2);
    ie_reg |= (1 << (irq % 32));

    __CSR_WRITE(CSR_MIREG2, ie_reg);
}

/**
 * @brief  Diasble CLIC interrupt.
 *
 * @details Clear CLIC IE bit for interrupt disable.
 *
 * @param[in]  irq  Number of interrupt input to disable.
 */
__STATIC_FORCEINLINE void __clic_DisableInt(INT_TYPE irq)
{
    uint32_t ie_reg;

    __CSR_WRITE(CSR_MISELECT, CLIC_IP_IE_BASE + irq / 32);

    ie_reg = __CSR_READ(CSR_MIREG2);
    ie_reg &= ~(1 << (irq % 32));

    __CSR_WRITE(CSR_MIREG2, ie_reg);
}

/**
 * @brief  Clear CLIC int pending status.
 *
 * @details Clear pending bit,no need to clear pending status if CLIC vectored mode is set,and int
 * trigger type is set to edge,otherwise software should call this function to clear pending status.
 *
 * @param[in]  irq   Number of interrupt input to be cleared.
 */
__STATIC_FORCEINLINE void __clic_ClearIntPending(INT_TYPE irq)
{
    uint32_t ip_reg;

    __CSR_WRITE(CSR_MISELECT, CLIC_IP_IE_BASE + irq / 32);

    ip_reg = __CSR_READ(CSR_MIREG);
    ip_reg &= ~(1 << (irq % 32));

    __CSR_WRITE(CSR_MIREG, ip_reg);
}

/**
 * @brief  Get given interrupt pending status.
 *
 * @param[in]  irq   Number of interrupt to be get pending status.
 *
 * @return true - Is pending.
 *         false - Is not pending.
 */
__STATIC_FORCEINLINE bool __clic_GetIntPending(INT_TYPE irq)
{
    bool     ret = false;
    uint32_t ip_reg;

    __CSR_WRITE(CSR_MISELECT, CLIC_IP_IE_BASE + irq / 32);
    ip_reg = __CSR_READ(CSR_MIREG);

    if ((ip_reg >> (irq % 32)) & 1)
    {
        ret = true;
    }

    return ret;
}

/**
 * @brief  Set trigger type for given interrupt input.
 *
 * @param[in]  irq    Number of interrupt to be set.
 * @param[in]  trig   Trigger Type to be set.
 */
__STATIC_FORCEINLINE void __clic_SetIntTrig(INT_TYPE irq, TRIG_TYPE trig)
{
    uint32_t attr_reg;
    uint8_t  attr_pos;

    attr_pos = irq % 4;
    attr_pos *= 8;
    __CSR_WRITE(CSR_MISELECT, CLIC_CTRL_ATTR_BASE + irq / 4);

    attr_reg = __CSR_READ(CSR_MIREG2);
    attr_reg &= ~((CLIC_ATTR_TRIG_MSK | CLIC_ATTR_POLARITY_MSK) << attr_pos);
    attr_reg |= (trig << (CLIC_ATTR_TRIG_POS + attr_pos));

    __CSR_WRITE(CSR_MIREG2, attr_reg);
}

/**
 * @brief  Get trigger type setting of given interrupt input.
 *
 * @param[in]  irq   Number of interrupt input.
 *
 * @return Tiger type setting of given interrupt input.
 */
__STATIC_FORCEINLINE TRIG_TYPE __clic_GetIntTrig(INT_TYPE irq)
{
    uint32_t attr_reg;
    uint8_t  attr_pos;

    attr_pos = irq % 4;
    attr_pos *= 8;
    __CSR_WRITE(CSR_MISELECT, CLIC_CTRL_ATTR_BASE + irq / 4);

    attr_reg = __CSR_READ(CSR_MIREG2);
    attr_reg >>= (attr_pos + CLIC_ATTR_TRIG_POS);

    return (TRIG_TYPE)attr_reg;
}

/**
 * @brief  Set interrupt to non-vectored or vectored mode.
 * @details IF interrupt is set none-vectored and when triggered,it jumps to the common
 * code at mtvec, otherwise it jumps to the trap-handler specified int mtvt.
 *
 * @param[in]  irq   Number of interrupt input.
 * @param[in]  shv   NONE_VECTORED_MODE - Non-vectored mode.
 *                   VECTORED_MODE - Vectored mode.
 */
__STATIC_FORCEINLINE void __clic_SetIntShv(INT_TYPE irq, SHV_TYPE shv)
{
    uint32_t attr_reg;
    uint8_t  attr_pos;

    attr_pos = irq % 4;
    attr_pos *= 8;
    __CSR_WRITE(CSR_MISELECT, CLIC_CTRL_ATTR_BASE + irq / 4);

    attr_reg = __CSR_READ(CSR_MIREG2);
    attr_reg &= ~(CLIC_ATTR_SHV_MSK << attr_pos);
    attr_reg |= (shv << (CLIC_ATTR_SHV_POS + attr_pos));

    __CSR_WRITE(CSR_MIREG2, attr_reg);
}

/**
 * @brief  Get interrupt vector mode setting.
 *
 * @param[in]  irq   Number of interrupt input.
 *
 * @return NONE_VECTORED_MODE - Non-vectored mode.
 *         VECTORED_MODE - Vectored mode.
 */
__STATIC_FORCEINLINE SHV_TYPE __clic_GetIntShv(INT_TYPE irq)
{
    uint32_t attr_reg;
    uint8_t  attr_pos;

    attr_pos = irq % 4;
    attr_pos *= 8;
    __CSR_WRITE(CSR_MISELECT, CLIC_CTRL_ATTR_BASE + irq / 4);

    attr_reg = __CSR_READ(CSR_MIREG2);
    attr_reg >>= attr_pos;

    return ((attr_reg & CLIC_ATTR_SHV_MSK) ? VECTORED_MODE : NONE_VECTORED_MODE);
}

/**
 * @brief  Set interrupt level and interrupt priority.
 * @details Interrupt level and interrupt priority deviation is defined by
 * mcliccfg register, please refer to function __clic_SetNlbits and __clic_GetNlbits.
 *
 * @param[in]  irq   Number of interrupt input.
 * @param[in]  priority   Specify interrupt level and interrupt priority.
 */
__STATIC_FORCEINLINE void __clic_SetIntPriority(INT_TYPE irq, uint8_t priority)
{
    uint32_t ctrl_reg;
    uint8_t  ctrl_pos;

    ctrl_pos = irq % 4;
    ctrl_pos *= 8;
    __CSR_WRITE(CSR_MISELECT, CLIC_CTRL_ATTR_BASE + irq / 4);

    ctrl_reg = __CSR_READ(CSR_MIREG);
    ctrl_reg &= ~(CLIC_CTRL_ALL_MSK << ctrl_pos);
    ctrl_reg |= (priority << (CLIC_CTRL_ALL_POS + ctrl_pos));

    __CSR_WRITE(CSR_MIREG, ctrl_reg);
}

/**
 * @brief  Get interrupt level and interrupt priority.
 * @details Interrupt level and interrupt priority deviation is defined by
 * mcliccfg register, please refer to function __clic_SetNlbits and __clic_GetNlbits.
 *
 * @param[in]  irq   Number of interrupt input.
 *
 * @return Interrupt level and interrupt priority setting.
 */
__STATIC_FORCEINLINE uint8_t __clic_GetIntPriority(INT_TYPE irq)
{
    uint32_t ctrl_reg;
    uint8_t  ctrl_pos;

    ctrl_pos = irq % 4;
    ctrl_pos *= 8;
    __CSR_WRITE(CSR_MISELECT, CLIC_CTRL_ATTR_BASE + irq / 4);

    ctrl_reg = __CSR_READ(CSR_MIREG);
    ctrl_reg >>= (CLIC_CTRL_ALL_POS + ctrl_pos);

    return ((uint8_t)ctrl_reg);
}

/**
