__STATIC_FORCEINLINE void __clic_SetNlbits(uint8_t mnlbits)
{
    uint32_t cfg_reg;

    __CSR_WRITE(CSR_MISELECT, CLIC_CFG_BASE);

    cfg_reg = __CSR_READ(CSR_MIREG);
    cfg_reg &= ~CLIC_CFG_NLBIT_MSK;
    cfg_reg |= (mnlbits << CLIC_CFG_NLBIT_POS);

    __CSR_WRITE(CSR_MIREG, cfg_reg);
}
