/**
 * @brief  Get PMAxCFG register by entry.
 *
 * @param[in]  entry   Region index.
 *
 * @return  PMAxCFG register value.
 */
__STATIC_FORCEINLINE uint8_t __pma_GetXCfg(wm_base_t entry)
{
    wm_csr_t cfg;

    WM_ASSERT(entry < __PMP_MIN_REGION_SIZE);

#if __riscv_xlen == 32
    cfg = __pma_GetCfgX(entry / 4);

    entry = entry % 4;
    entry = entry << 3;
#elif __riscv_xlen == 64
    cfg = __pma_GetCfgX((entry / 8) * 2);

    entry = entry % 8;
    entry = entry << 3;
#else
#error "XLEN invalid.\n"
#endif

    return (uint8_t)(cfg >> entry);
}

/**
 * @brief  Set PMAxCFG by entry.
 *
 * @param[in]  entry   PMAx region index.
 * @param[in]  xcfg    PMAxCFG register value to set.
 *
 * @retval RET_OK   If the procedure was successful.
 * @retval RET_ERR_PMP_ENTRY_NUM_UNVALID   Given entry is unvalid.
 */
__STATIC_FORCEINLINE wm_status_t __pma_SetXCfg(wm_base_t entry, uint8_t xcfg)
{
    wm_status_t ret = RET_OK;
    wm_base_t idx;
    wm_csr_t  cfg;

    WM_ASSERT_RET(entry < __PMP_MIN_REGION_SIZE, RET_ERR_PMP_ENTRY_NUM_UNVALID);

#if __riscv_xlen == 32
    idx   = entry / 4;
    entry = entry % 4;
#elif __riscv_xlen == 64
    idx   = (entry / 8) * 2;
    entry = entry % 8;
#else
#error "XLEN invalid.\n"
#endif //__riscv_xlen == 32

    cfg = __pma_GetCfgX(idx);

    entry = entry << 3;
    cfg   &= ~(0xff << entry);
    cfg   |= (xcfg << entry);

    ret = __pma_SetCfgX(idx, cfg);

    return ret;
}

