/**
 * @brief  Get order of a given PMP region size. 
 * 
 * @param[in]  size   PMP region size.
 * 
 * @return Order of region size. 
 */
__STATIC_FORCEINLINE uint8_t get_order(wm_base_t size)
{
    uint8_t order;

#ifdef __riscv_isa_zbb
    order = __riscv_ctz_32(size);
#else 
    order = log2(size);
#endif     

    return order;
}

