/**
 * @brief Define system clock frequency.
 */
#define  SYSTEM_CLOCK    (100000000)

/**
 * \defgroup WMSIS_Core_System_Config_Functions       System Configuration Functions
 * @brief   Functions for system initialize and trap functions available in system_<device>.c.
 * @details  In system_device.c file contines system configuration   
 *  -  System exception and interrupt init function
 *  -  System default exception and interrupt handler function
 *  -  System exception and interrupt register function
 *  -  Delay_ms function is used to delay time at the millisecond level
 * @{
 */

/**
 * @brief Machine mode interrupt handler function type.
 */
typedef __MACHINE_INTERRUPT void (*vector_int_handler)(void);

/**
 * @brief  Store the exception handlers for each exception ID.
 * @details This SysExcHandlers are used to store all the handlers for all
 * the exception of CPU core. In System trap init all exception handler are registered to \ref System_DefaultExcHandler
 */
static exc_handler SysExcHandlers[MAX_EXC_NUM];

/**
 * @brief  Store all interrupt handlers for each interrupt ID.
 * @details This SysIntHandlers are used to store all the handlers for all
 * the interrupt include system interrupt and external interrupt. In System trap init all interrupt handler are registered to \ref System_DefaultIntHandler
 * @note    SysIntHandlers must align to 64 byte for MTVEC.base is in high 26 bit.
 */
static void* SysIntHandlers[MAX_INT_NUM] __attribute__((aligned(64)));

static int_handler SysNMIHandler = NULL;

/**
 * @brief  Clic machine mode software interrupt handler.
 * @details Clear software interrupt pending state when trap in clic software interrupt. 
 * @note    This function is only used for clic vector mode machine software interrupt.
 *          Users can write your own System_MsiHandler in application.
 */
__WEAK void System_MsiHandler(void)
{
    SYS_PRINT("Software Interrupt Triggered!");
    SysTimer_ClearSWIRQ();
#if defined(__CLIC_PRESENT) && (__CLIC_PRESENT == 1)      
    __clic_ClearIntPending(SW_INT);
#endif    
}

/**
 * @brief  Clic machine mode software interrupt handler.
 * @details Clear software interrupt pending state when trap in clic software interrupt. 
 * @note    This function is only used for clic vector mode machine software interrupt.
 *          Users can write your own System_MsiHandler in application.
 */
__WEAK void System_MtiHandler(void)
{
    SYS_PRINT("Timer Interrupt Triggered!");
    SysTimer_Stop();
    SysTick_Reload(SYSTEM_CLOCK / 100);
}

/**
 * @brief  Simulator exit function.   
 * @details This function is used to exit simulation.
 */
static void System_SimExit(void)
{
    /* simulatior exit */
    __ASM_VOLATILE("li x10, 0xcdcdcdcd");
    __ASM_VOLATILE("li x11, 0x900d900d");
}

/**
 * @brief  Print register value saved in Stack
 * @details Print caller-save registers saved in stack when trap into exception or interrupt for debug.
 * @param[in]  sp  stack pointer
 */
static void trap_context_print(unsigned long sp)
{
    CONTEXT_TYPE* context = (CONTEXT_TYPE*) sp;
    SYS_PRINT("ra:0x%lx tp:0x%lx t0:0x%lx\r\n", context->ra, context->tp, context->t0);
    SYS_PRINT("t1:0x%lx t2:0x%lx a0:0x%lx a1:0x%lx a2:0x%lx a3:0x%lx a4:0x%lx\r\n", \
    context->t1, context->t2, context->a0, context->a1, context->a2, context->a3, context->a4);
    SYS_PRINT("a5:0x%lx a6:0x%lx a7:0x%lx t3:0x%lx t4:0x%lx t5:0x%lx t6:0x%lx\r\n", \
    context->a5, context->a5, context->a7, context->t3, context->t4, context->t5, context->t6);
}

/**
 * @brief  System Default Exception Handler
 * @details This function provides a default exception handler for all exception ids.
 * By default, It will just print some register value in stack for debug, Users can customize it according to its requirements.
 * @param[in]  cause  code indicating the reason that caused the trap in machine mode
 * @param[in]  sp     stack pointer
 */
void System_DefaultExcHandler(unsigned long cause, unsigned long sp)
{
    CONTEXT_TYPE* context = (CONTEXT_TYPE*) sp;
    SYS_PRINT("Default Exception Handler:\n");
    SYS_PRINT("mcause:0x%lx mepc:0x%lx mstatus:0x%lx\r\n", cause, context->mepc, context->mstatus);
    trap_context_print(sp);

    while (1);
}

/**
 * @brief  System Default NMI Handler
 * @details This function provides a default NMI handler for NMI interrupt.
 * By default, It will just print some register value in stack for debug, Users can customize it according to its requirements.
 * @param[in]  cause  code indicating the reason that caused the trap in machine mode
 * @param[in]  sp     stack pointer
 */
void System_DefaultNMIHandler(unsigned long cause, unsigned long sp)
{
    wm_csr_t epc,status;

#if defined(__RNMI_PRESENT) && (__RNMI_PRESENT == 1)
    epc    = __CSR_READ(CSR_MNEPC);
    status = __CSR_READ(CSR_MNSTATUS);
#else
    epc    = __CSR_READ(CSR_MEPC);
    status = __CSR_READ(CSR_MSTATUS);
#endif
    SYS_PRINT("cause:0x%lx epc:0x%lx status:0x%lx\r\n",cause,epc,status);
    trap_context_print(sp);

    while (1);
}

/**
 * @brief  System Default interrupr Handler
 * @details This function provides a default interrupt handler for System interrupt in clint mode.
 * By default, It will just print some SCR register value for debug, Users can customize it according to its requirements.
 * @param[in]  cause  code indicating the reason that caused the trap in machine mode
 * @param[in]  sp     stack pointer
 * @note    This function is used for clint interrupt.
 */
void System_DefaultIntHandler(unsigned long cause, unsigned long sp)
{
    SYS_PRINT("Default Interrupt Handler:\n");
    SYS_PRINT("mcause:0x%lx",cause);
    SYS_PRINT("mepc:0x%lx",__CSR_READ(CSR_MEPC));
    SYS_PRINT("mstatus:0x%lx",__CSR_READ(CSR_MCAUSE));
    SYS_PRINT("mie:0x%lx", __CSR_READ(CSR_MIE));
    SYS_PRINT("mip:0x%lx", __CSR_READ(CSR_MIP));
    while (1);
}

/**
 * @brief  System Default interrupr Handler
 * @details This function provides a default interrupt handler for System interrupt in clic mode.
 * By default, It will just print some SCR register value for debug, Users can customize it according to its requirements.
 * @param[in]  cause  code indicating the reason that caused the trap in machine mode
 * @param[in]  sp     stack pointer
 * @note    This function is used for clic interrupt.
 */
void System_DefaultClicHandler(unsigned long cause, unsigned long sp)
{
    SYS_PRINT("Default Interrupt Handler:\n");
    SYS_PRINT("mcause:0x%lx",cause);
    SYS_PRINT("mepc:0x%lx",__CSR_READ(CSR_MEPC));
    SYS_PRINT("mstatus:0x%lx",__CSR_READ(CSR_MCAUSE));
    SYS_PRINT("mie:0x%lx", __CSR_READ(CSR_MIE));
    SYS_PRINT("mip:0x%lx", __CSR_READ(CSR_MIP));
    while (1);
}

/**
 * @brief  System trap handler function
 * @details This function provides system trap handler for all system exception and none vector mode interrupt of clint and clic.
 * If an exception causes entry into this function, it will call exception handler corresponding to the exception id in \ref SysExcHandlers[id].
 * If an interrupt causes entry into this function, it will call interrupt handler corresponding to the interrupt id in \ref SysIntHandlers[id].
 * @param[in]  sp     stack pointer
 */
void System_TrapHandler(unsigned long cause, unsigned long sp)
{
    int_handler intHandler;
    exc_handler excHandler;
    wm_base_t exccode = cause & MCAUSE_EXCCODE;

    if (cause & MCAUSE_INT) {
        intHandler  = SysIntHandlers[exccode];
        if (NULL != intHandler) 
        {
            intHandler(cause, sp);
        }
    } 
    else 
    {
        excHandler = SysExcHandlers[exccode];
        if (NULL != excHandler) 
        {
            excHandler(cause, sp);
        } 
    }
}

/**
 * @brief Non-Maskable Interrupt (NMI) handler for the system.
 *
 * This function is called when an NMI occurs. It checks if a custom NMI handler
 * (`SysNMIHandler`) is registered and invokes it with the provided parameters.
 *
 * @param cause The cause of the NMI 
 * @param sp    The stack pointer at the time of the NMI. This can be used for
 *              debugging or context analysis.
 * @warning This function should be called only in an NMI context. It does not
 *          perform any recovery or system reset operations by default.
 */
void System_NMIHandler(unsigned long cause, unsigned long sp)
{
    if (NULL != SysNMIHandler) 
    {
        SysNMIHandler(cause, sp);
    }
}

/*----------------------------------------------------------------------------
  System exception handler register function
 *----------------------------------------------------------------------------*/
/**
 * @defgroup handler_register_functions Excetion and Interrupt Register Functions
 * @brief   Register exception and interrupt handler
 * @{
 */

/**
 * @brief  system exception handler register
 * @details This function used to register exception handler, modify SysExcHandlers[excn] to handler.
 * 
 * @param[in]  excn     core exception number
 * @param[in]  handler  The core exception handler for this exception 
 * 
 * @return  None
 */
wm_status_t System_ExcHandlerRegister(EXC_TYPE excn, exc_handler handler)
{
    WM_ASSERT_RET((excn < MAX_EXC_NUM), RET_ERR_EXC_ID_INVALID);
    WM_ASSERT_RET((NULL != handler), RET_ERR_COMM_PTR_NULL);

    SysExcHandlers[excn] = handler;

    return RET_OK;
}

#if defined(__CLIC_PRESENT) && (__CLIC_PRESENT == 1)
/*----------------------------------------------------------------------------
  System interrupt handler register function
 *----------------------------------------------------------------------------*/
/**
 * @brief  Clic interrupt handler register
 * @details  This function use to configure vector mode, trigger mode and interrupt level and priority for a specific clic interrupt and register its interrupt handler.
 * @param[in]   irq       Interrupt number
 * @param[in]   shv       0 : non-vector mode 1 : vector mode
 * @param[in]   trig      Set clic interrupt trigger type. \sa See TRIG_TYPE for more information
 * @param[in]   priority  Set interrupt level and priority.
 * @param[out]  handler   interrupt handler, if NULL, handler will not be installed
 * @return               0 register success
                0x80050001 register fail because invalid int number
                         2 register fail because handler is NULL
*/
wm_status_t System_ClicHandlerRegister(INT_TYPE irq, bool shv, TRIG_TYPE trig, uint8_t priority, void* handler)
{
    WM_ASSERT_RET((irq < MAX_INT_NUM), RET_ERR_INT_ID_INVALID);
    WM_ASSERT_RET((NULL != handler), RET_ERR_COMM_PTR_NULL);

    /* set interrupt vector mode */
    __clic_SetIntShv(irq, shv);
    /* set interrupt trigger mode and polarity */
    __clic_SetIntTrig(irq, trig);
    /*set interrupt level and priority*/
    __clic_SetIntPriority(irq, priority);
    SysIntHandlers[irq] = handler;

    if (VECTORED_MODE == shv)
    {
        __ASM_VOLATILE("fence.i");
    }    
    return RET_OK;
}

/*----------------------------------------------------------------------------
  System exception and interrupt init function
 *----------------------------------------------------------------------------*/

/**
 * @brief  Clic interrupt initialization
 * @details Configure clic registers to initialize clic interrupt
 *  - Set trap_entry function to MTVEC register as clic none vector interrupt and exception common enty.
 *  - Set \ref SysIntHandlers to MTVT register as clic vector table base address
 *  - Set clic mintthresh.th to 0
 *  - Set nlbits = 2
 */
void System_ClicInit(void)
{
    __clic_SetIntVector((unsigned long)trap_entry);  
    __clic_SetExtVector((unsigned long)SysIntHandlers);

    __clic_SetThresh(0);
    __clic_SetNlbits(2);
}
#else

/**
 * @brief  Clint interrupt handler register
 * @details This function use to register a specific clint interrupt handler.
 * @param[in]  irq      Interrupt number
 * @param[in]  handler  interrupt handler, if NULL, handler will not be installed
 * @return           0  register success
 *                   2  register fail because handler is NULL
 *          0x80050001  register fail because invalid int number
 * @note    This function only realize when clic NOT present.
*/
wm_status_t System_ClintHandlerRegister(INT_TYPE irq, int_handler handler)
{
    WM_ASSERT_RET((irq < MAX_INT_NUM), RET_ERR_INT_ID_INVALID);
    WM_ASSERT_RET((NULL != handler), RET_ERR_COMM_PTR_NULL);

    SysIntHandlers[irq] = handler;
    return RET_OK;
}
/** @} end of group handler_register_functions */

/**
 * @brief  Clint interrupt Initialization
 * @details This function used initial clint interrupt configuration including : 
 * set clint interrupt and system exception common entry to function trap_entry
 * set clint interrupt none vector mode.
 * @note    This function only realize when clic NOT present.
 */
void  System_ClintInit(void)
{
    __clint_SetVector((unsigned long)trap_entry, VEC_DIRECT);
}
#endif

#if defined(__NMI_PRESENT) && (__NMI_PRESENT == 1)
wm_status_t System_NMIHandlerRegister(int_handler handler)
{
    WM_ASSERT_RET((NULL != handler), RET_ERR_COMM_PTR_NULL);

    SysNMIHandler = handler;

    return RET_OK;
}
#endif

/**
 * @defgroup SYSTEM_INIT_FUNCTIONS System Initialize Functions  
 * @{
 */

/**
 * @brief  System trap initialization
 * @details This function used to initial trap including :
 *  - register are the exception handler to default System_DefaultExcHandler.
 *  - If clic present, call \ref System_ClicInit to initial clic interrupt and register software interrupt to System_MsiHandler
 *   - register system timer interrupt to System_MtiHandler
 *   - register other interrupt to System_DefaultClicHandler.
 *  - If clic NOT present, call \ref System_ClintInit to initial clint interrupt and register all clint interrupt to default System_DefaultIntHandler
 *  - If NMI present, register NMI handler register.
 */
void System_TrapInit(void)
{
    wm_base_t i;

    for(i = 0; i < MAX_EXC_NUM; i++)
    {
        System_ExcHandlerRegister(i, System_DefaultExcHandler);
    }

#if defined(__CLIC_PRESENT) && (__CLIC_PRESENT == 1)
    System_ClicInit();
    for(i = 0; i < MAX_INT_NUM; i++)
    {
        System_ClicHandlerRegister(i, NONE_VECTORED_MODE, TRIG_HIGH_LEVEL, DEFAULT_INT_PRIORITY, System_DefaultClicHandler);
    }
    System_ClicHandlerRegister(SW_INT, NONE_VECTORED_MODE, TRIG_HIGH_LEVEL, DEFAULT_INT_PRIORITY, System_MsiHandler); 
    System_ClicHandlerRegister(TIMER_INT, NONE_VECTORED_MODE, TRIG_HIGH_LEVEL, DEFAULT_INT_PRIORITY, System_MtiHandler);   
#else
    System_ClintInit();
    for(i = 0; i < MAX_INT_NUM; i++)
    {
        System_ClintHandlerRegister(i, System_DefaultIntHandler);
    } 
#endif

#if defined(__NMI_PRESENT) && (__NMI_PRESENT == 1)
    System_NMIHandlerRegister(System_DefaultNMIHandler);

#if defined(__RNMI_PRESENT) && (__RNMI_PRESENT == 1)    
    __nmi_EnableInt();
#endif //__RNMI_PRESENT   

#endif //__NMI_PRESENT
}

