/*----------------------------------------------------------------------------
  Delay Function
 *----------------------------------------------------------------------------*/

/**
 * @brief  Delay function API 
 * @details Delay_ms function is used to delay time at the millisecond level
 * @param[in]  n_ms: count in milliseconds
 * @remarks    This function reads and writes the MCYCLE register to implement the delay function
 * make sure MCOUNTINHIBIT.cy is set to 0(default) then MCYCLE increase with system clock cycle. 
 */
void delay_ms(unsigned long n_ms)
{   
    uint32_t start_cnt, cur_cnt;
    uint32_t offset_cnt = (n_ms * SYSTEM_CLOCK) / 1000;
    int32_t  delta_cnt;

#if defined(__MCYCLE_PRESENT) && (__MCYCLE_PRESENT == 1)
    start_cnt = __CSR_READ(CSR_MCYCLE);
    do {
        cur_cnt   = __CSR_READ(CSR_MCYCLE);
        delta_cnt = cur_cnt - start_cnt;
        if (delta_cnt < 0)
        {
            delta_cnt += 0xffffffff;
        }
    } while (delta_cnt < offset_cnt);
#endif //__MCYCLE_PRESENT    
}
/**@} end of group WMSIS_Core_System_Config_Functions */

